import{z as o,x as s,o as e,c as D,q as r,j as A,D as a,d as l,s as t,S as n,b as i}from"./chunks/framework.C8m1ZpeB.js";const h=JSON.parse('{"title":"评测：FID 管线","description":"","frontmatter":{"title":"评测：FID 管线","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/diff-fid-pipeline.md","filePath":"llm/diff-fid-pipeline.md","lastUpdated":1791413859000}'),d={name:"llm/diff-fid-pipeline.md"};function F(p,E,C,f,I,m){const B=s("Mermaid");return e(),D("div",null,[E[2]||(E[2]=r('<h1 id="评测-fid-管线" tabindex="-1">评测：FID 管线 <a class="header-anchor" href="#评测-fid-管线" aria-label="Permalink to &quot;评测：FID 管线&quot;">​</a></h1><div class="epigraph"><p>FID 是两个高斯之间的距离，不是两张图之间的距离；它对「整体分布漂了没有」敏感，对「这张图的手指对不对」失明。</p><footer>—— Heusel 等, GANs Trained by a Two Time-Scale Update Rule Converge to a Local Nash Equilibrium, 2017</footer></div><p><a href="/llm/diff-cost-engineering">上一课</a>把每图成本立成账，并要求改动报「单价增量与质量增量」两条。质量增量的口径从哪来，是本课的题目：把 FID 与配对指标做成一条可复现的评测管线，让蒸馏、量化、调度的每一次改动都有同一把尺。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>FID 的定义简单：把真实图像与生成图像分别过 Inception 网络取特征，各自拟合成高斯，算两个高斯之间的 Fréchet 距离。麻烦全在管线工程上：样本量小时 FID 系统性偏高，10k 与 50k 样本算出的不是同一个数；参考统计换了数据集、分辨率或特征模型就不可比；VAE 解码路径与线上不一致时，测的是解码器不是去噪网络。更根本的失明：FID 衡量分布层面的整体相似，对提示词贴合度、局部结构缺陷几乎不敏感——只看 FID 的团队会放行「分布很像但答非所问」的回归。缺口是一组互相补位的指标加一条钉死变量的管线。</p><p><span class="marginnote">直觉理解 FID：它像比较「两群人的体检报告」——不是逐个人对照，而是比较两群人的平均值和波动幅度（特征均值与协方差）。所以它说得出「这一批整体偏了」，说不出「张三的手指画错了六个」；后者要靠别的指标补位。</span></p><h3 id="指标的分工" tabindex="-1">指标的分工 <a class="header-anchor" href="#指标的分工" aria-label="Permalink to &quot;指标的分工&quot;">​</a></h3><ul><li><strong>FID</strong>：整体分布是否漂移，适合抓量化与蒸馏的系统性退化。</li><li><strong>CLIPScore</strong>：图像与提示词的对齐度，抓「答非所问」。</li><li><strong>人评抽检</strong>：固定提示词集上的偏好对比，抓高频纹理与结构缺陷，做最后裁决。</li><li><strong>线上延迟分位数</strong>：与质量同表报告；省出的钱要能对上省出的毫秒。</li></ul><p><span class="marginnote">同一模型 10k 样本的 FID 系统性高于 50k 样本的值；文献口径用 50k（Heusel 等 2017）。横比的前提是样本量、参考统计、特征模型三项全同——差任何一项，比较作废。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>管线六步，全部进 CI：</p><ol><li><strong>冻结参考</strong>：参考统计（特征均值与协方差）按数据集与分辨率一次性算好存档，版本化。</li><li><strong>固定采样</strong>：固定种子集生成评测样本；样本量最少 10k，能负担则 50k。</li><li><strong>同路径解码</strong>：评测图像走与线上相同的 VAE 解码与后处理路径，测的才是服务输出。</li><li><strong>成对基线</strong>：每次改动与改动前的版本同种子、同提示词集成对比较，报 FID 增量、CLIPScore 增量与人评胜负率。</li><li><strong>门禁</strong>：FID 劣化超阈值或人评显著落败即拦下；阈值按改动类型分级——量化改动与调度改动的容忍度不同。</li><li><strong>报告入账</strong>：结果连同样本量、参考统计版本、种子集版本一起存档，进<a href="/llm/diff-cost-engineering">成本工程</a>的改动门禁。</li></ol><p><span class="marginnote">常见误区：评测脚本用 FP32、线上服务用 FP16，还纳闷为什么指标好看、线上变丑——解码与预处理路径不同，测出来的其实是另一个系统。「同路径解码」这一步就是给这类坑立的规矩。</span></p>',13)),(e(),A(n,null,{default:a(()=>[t(B,{id:"mermaid-85",class:"mermaid",graph:"flowchart%20TD%0A%20%20FRZ%5B%22%E5%86%BB%E7%BB%93%E5%8F%82%E8%80%83%E7%BB%9F%E8%AE%A1%EF%BC%9A%E7%89%88%E6%9C%AC%E5%8C%96%22%5D%20--%3E%20GEN%5B%22%E5%9B%BA%E5%AE%9A%E7%A7%8D%E5%AD%90%E9%9B%86%E7%94%9F%E6%88%90%E6%A0%B7%E6%9C%AC%EF%BC%9A10k-50k%22%5D%0A%20%20GEN%20--%3E%20DEC%5B%22%E4%B8%8E%E7%BA%BF%E4%B8%8A%E5%90%8C%E8%B7%AF%E5%BE%84%E8%A7%A3%E7%A0%81%22%5D%0A%20%20DEC%20--%3E%20FID%5B%22FID%EF%BC%9A%E6%8A%93%E6%95%B4%E4%BD%93%E5%88%86%E5%B8%83%E6%BC%82%E7%A7%BB%22%5D%0A%20%20DEC%20--%3E%20CLP%5B%22CLIPScore%EF%BC%9A%E6%8A%93%E7%AD%94%E9%9D%9E%E6%89%80%E9%97%AE%22%5D%0A%20%20DEC%20--%3E%20HUM%5B%22%E4%BA%BA%E8%AF%84%E6%8A%BD%E6%A3%80%EF%BC%9A%E6%8A%93%E5%B1%80%E9%83%A8%E7%BC%BA%E9%99%B7%22%5D%0A%20%20FID%20--%3E%20GATE%7B%22%E9%97%A8%E7%A6%81%EF%BC%9A%E5%8A%A3%E5%8C%96%E8%B6%85%E9%98%88%E5%80%BC%EF%BC%9F%22%7D%0A%20%20CLP%20--%3E%20GATE%0A%20%20HUM%20--%3E%20GATE%0A%20%20GATE%20--%3E%7C%E8%BF%87%7C%20OK%5B%22%E5%85%A5%E8%B4%A6%E5%90%88%E5%B9%B6%22%5D%0A%20%20GATE%20--%3E%7C%E4%B8%8D%E8%BF%87%7C%20BLOCK%5B%22%E6%8B%A6%E4%B8%8B%EF%BC%8C%E5%BD%92%E5%9B%A0%E5%88%B0%E6%94%B9%E5%8A%A8%E5%B1%82%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[l(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=i("h2",{id:"机制",tabindex:"-1"},[l("机制 "),i("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=i("p",null,"为什么成对比较是核心：FID 的绝对值没有意义，有意义的只是同协议下的差值。固定种子与提示词集后，两次评测之间唯一的变量就是被测改动，差值才能归因——这正是前几课「一次只动一个旋钮」的评测面。为什么人评不可替代：蒸馏丢的细节与量化出的怪纹常集中在少数提示词与局部区域，分布指标被大量正常图像稀释后看不见；小规模成对人评（几十到几百票）对这类退化的检出率远高于 FID。",-1)),(e(),A(n,null,{default:a(()=>[t(B,{id:"mermaid-92",class:"mermaid",graph:"flowchart%20LR%0A%20%20subgraph%20BASE%5B%22%E5%9F%BA%E7%BA%BF%E7%89%88%E6%9C%AC%22%5D%0A%20%20%20%20B1%5B%22%E5%90%8C%E4%B8%80%E6%89%B9%E7%A7%8D%E5%AD%90%22%5D%20--%3E%20B2%5B%22%E5%90%8C%E4%B8%80%E6%8F%90%E7%A4%BA%E8%AF%8D%E9%9B%86%22%5D%20--%3E%20B3%5B%22FID0%20%2F%20CLIP0%20%2F%20%E4%BA%BA%E8%AF%84%E8%83%9C%E7%8E%87%22%5D%0A%20%20end%0A%20%20subgraph%20NEW%5B%22%E6%94%B9%E5%8A%A8%E5%90%8E%E7%89%88%E6%9C%AC%22%5D%0A%20%20%20%20N1%5B%22%E5%90%8C%E4%B8%80%E6%89%B9%E7%A7%8D%E5%AD%90%22%5D%20--%3E%20N2%5B%22%E5%90%8C%E4%B8%80%E6%8F%90%E7%A4%BA%E8%AF%8D%E9%9B%86%22%5D%20--%3E%20N3%5B%22FID1%20%2F%20CLIP1%20%2F%20%E4%BA%BA%E8%AF%84%E8%83%9C%E7%8E%87%22%5D%0A%20%20end%0A%20%20B3%20--%3E%20D%5B%22%E4%B8%A4%E7%BB%84%E4%B9%8B%E9%97%B4%E5%94%AF%E4%B8%80%E5%8F%98%E9%87%8F%20%3D%20%E8%A2%AB%E6%B5%8B%E6%94%B9%E5%8A%A8%3Cbr%2F%3E%E5%B7%AE%E5%80%BC%E6%89%8D%E5%8F%AF%E5%BD%92%E5%9B%A0%22%5D%0A%20%20N3%20--%3E%20D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[l(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=r('<p><span class="marginnote">数字感受「稀释」：假设某缺陷只出现在 5% 的提示词上。它在 5 万张图的 FID 里被海量正常图摊薄到几乎不动；但 200 票的成对人评里仍有约 10 票正面撞上缺陷区，胜负率立刻现形。这就是分布指标失明、小样本人评反而灵的原因。</span></p><p>为什么参考统计要当作数据资产管理：它定义了「分布正确」的锚点。换参考等于换考纲；分辨率升级、数据集换代时参考统计必须重算并升版本，历史结果与新版不可比，报告里要断代。特征模型同理：换 Inception 的变体或权重，整条历史基线作废。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>FID 管线测分布质量与对齐，测不了安全与水印——那是下一课的门。它也测不了交互体验：延迟分位数由服务埋点供数，评测管线只汇总。人评有自己的协议问题（评委疲劳、提示词泄漏、排序偏置），抽检规模上去之前先钉协议，否则省下的 FID 预算会赔在人评方差里。最后，评测不是发布后的仪式：管线在改动合并前跑，线上再以抽样式人评校准「指标过了但用户不满意」的残余误差——两个环节都不可省。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>FID 测分布层面的漂移，对贴合度与局部缺陷失明，必须配 CLIPScore 与人评。</li><li>可比性的前提三项全同：样本量、参考统计、特征模型；参考统计版本化断代。</li><li>评测样本走线上同路径解码，测的才是服务输出而非实验脚本输出。</li><li>成对比较钉死变量：同种子、同提示词集，差值才可归因。</li><li>质量增量与单价增量同表报告，进改动的统一门禁。</li><li>出处：Heusel 等 2017（FID）；Hessel 等 2021（CLIPScore）；管线口径据本课整理。</li></ul>',6))])}const g=o(d,[["render",F]]);export{h as __pageData,g as default};
